<script lang="ts">
 import { enhance } from "$app/forms";
 import { Button, PageHeader } from "@zendev-lab/spark-ui";
 let {data,form}=$props();const t=$derived(data.messages.personal);const f=$derived(t.subscriptionFields);const v=$derived(form && "values" in form ? form.values : undefined);const selected=$derived(data.selected);
 const currencies=["CNY","USD","EUR","GBP","JPY"] as const;const cycles=["Daily","Weekly","Monthly","Quarterly","Yearly","Lifetime"] as const;const statuses=["Active","Cancelled","Paused","Expired"] as const;
 const money=(value:number,currency:string)=>new Intl.NumberFormat(data.locale,{style:"currency",currency}).format(value);
</script>
<svelte:head><title>{t.subscriptions} · Ulota</title></svelte:head>
<PageHeader title={t.subscriptions} lede={f.description} />
<form method="GET"><label>{f.search}<input type="search" name="q" value={data.filters.search}/></label><label>{f.status}<select name="status" value={data.filters.status??""}><option value="">{f.all}</option>{#each statuses as status}<option value={status}>{f[status]}</option>{/each}</select></label><label>{f.currency}<select name="currency" value={data.filters.currency??""}><option value="">{f.all}</option>{#each currencies as currency}<option value={currency}>{currency}</option>{/each}</select></label><label>{f.category}<select name="category" value={data.filters.category??""}><option value="">{f.all}</option>{#each data.categories as category}<option value={category}>{category}</option>{/each}</select></label><Button type="submit" variant="secondary">{f.filter}</Button></form>
<p class="summary">{f.total}: {data.stats.total_subscriptions} · {f.Active}: {data.stats.active_subscriptions} · {f.upcoming}: {data.stats.upcoming_payments}</p>
<section aria-labelledby="subscription-costs"><h2 id="subscription-costs">{f.costs}</h2><p>{f.estimateNote}</p>{#if Object.keys(data.stats.byCurrency).length===0}<p>{f.emptyCosts}</p>{:else}<table><thead><tr><th>{f.currency}</th><th>{f.monthly}</th><th>{f.yearly}</th><th>{f.estimatedSpent}</th></tr></thead><tbody>{#each Object.entries(data.stats.byCurrency) as [currency,cost] (currency)}<tr><th scope="row">{currency}</th><td>{money(cost.monthly_cost,currency)}</td><td>{money(cost.yearly_cost,currency)}</td><td>{money(cost.estimated_spent,currency)}</td></tr>{/each}</tbody></table>{/if}</section>
{#if form?.failed}<p role="alert">{form.code==="conflict"?f.conflict:t.failure}</p>{/if}{#if form?.saved}<p role="status">{t.saved}</p>{/if}
<section aria-labelledby="subscription-editor"><h2 id="subscription-editor">{selected?f.edit:f.add}</h2><form method="POST" action="?/save" use:enhance class="editor">
<input type="hidden" name="id" value={v?.id??selected?.id??""}/><input type="hidden" name="expectedRevision" value={v?.expectedRevision??selected?.revision??""}/><input type="hidden" name="operationId" value={v?.operationId??data.operationId}/>
<label>{f.name}<input name="name" value={v?.name??selected?.name??""} required/></label><label>{f.price}<input type="number" min="0" step="any" name="price" value={v?.price??selected?.price??0} required/></label>
<label>{f.currency}<select name="currency" value={v?.currency??selected?.currency??"CNY"}>{#each currencies as currency}<option value={currency}>{currency}</option>{/each}</select></label>
<label>{f.cycle}<select name="billing_cycle" value={v?.billing_cycle??selected?.billing_cycle??"Monthly"}>{#each cycles as cycle}<option value={cycle}>{f[cycle]}</option>{/each}</select></label><label>{f.cycleAmount}<input type="number" min="1" step="1" name="cycle_amount" value={v?.cycle_amount??selected?.cycle_amount??1} required/></label>
<label>{f.startDate}<input type="date" name="start_date" value={v?.start_date??selected?.start_date??data.today} required/></label><label>{f.nextPayment}<input type="date" name="next_payment_date" value={v?.next_payment_date??selected?.next_payment_date??""}/><small>{selected?f.clearNext:f.automaticNext}</small></label>
<label>{f.status}<select name="status" value={v?.status??selected?.status??"Active"}>{#each statuses as status}<option value={status}>{f[status]}</option>{/each}</select></label><label>{f.category}<input name="category" value={v?.category??selected?.category??""}/></label>
<label>{f.website}<input name="website" type="url" value={v?.website??selected?.website??""}/></label><label>{f.logo}<input name="logo_url" type="url" value={v?.logo_url??selected?.logo_url??""}/></label><label>{f.paymentMethod}<input name="payment_method" value={v?.payment_method??selected?.payment_method??""}/></label><label>{f.reminderDays}<input name="reminder_days" type="number" min="0" step="1" value={v?.reminder_days??selected?.reminder_days??3} required/><small>{f.noScheduler}</small></label>
<label class="checkbox"><input name="auto_renew" type="checkbox" checked={v ? v.auto_renew==="on" : selected?.auto_renew??true}/>{f.autoRenew}</label><label class="wide">{f.notes}<textarea name="notes" rows="3" value={v?.notes??selected?.notes??""}></textarea></label><div class="wide actions"><Button type="submit">{t.save}</Button>{#if selected}<Button href="/personal/subscriptions" variant="ghost">{f.cancelEditing}</Button>{/if}</div>
</form></section>
<section aria-label={t.subscriptions}>{#if data.items.length===0}<p>{f.empty}</p>{:else}<ul>{#each data.items as item (item.id)}<li><div class="heading"><strong>{item.name}</strong><span>{money(item.price,item.currency)} · {f[item.billing_cycle]} × {item.cycle_amount}</span></div><p>{f[item.status]} · {f.nextPayment}: {item.next_payment_date??f.none} · {item.category}</p>{#if item.notes}<p class="notes">{item.notes}</p>{/if}<div class="actions"><Button variant="ghost" href="?edit={encodeURIComponent(item.id)}">{f.edit}</Button>{#each ["renew","cancel","delete"] as action}<form method="POST" action={`?/${action}`} use:enhance><input type="hidden" name="id" value={item.id}/><input type="hidden" name="expectedRevision" value={item.revision}/><input type="hidden" name="operationId" value={data.recordOperations[item.id][action as "renew"|"cancel"|"delete"]}/><Button type="submit" variant={action==="delete"?"danger":"secondary"} disabled={action==="renew"&&item.billing_cycle==="Lifetime"}>{action==="renew"?f.renew:action==="cancel"?f.cancelSubscription:f.delete}</Button></form>{/each}</div></li>{/each}</ul>{/if}</section>
<style>.editor {align-items:start;display:grid !important;grid-template-columns:repeat(2,minmax(0,1fr));}.wide{grid-column:1/-1;}.editor input:not([type=checkbox]),.editor select,.editor textarea{width:100%;box-sizing:border-box;}.checkbox{display:flex !important;align-items:center;}.actions,.heading{display:flex;gap:.5rem;align-items:center;flex-wrap:wrap;}.heading{justify-content:space-between;}.notes{white-space:pre-wrap;}ul{list-style:none;padding:0;}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums;}td,th{text-align:start;padding:.75rem .4rem;border-bottom:1px solid var(--color-border);}.summary{margin-block:2rem;}@media(max-width:40rem){.editor{grid-template-columns:minmax(0,1fr);}table{font-size:.875rem;}}</style>
